package com.example.grpc.cache

import io.grpc.stub.StreamObserver
import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.util.concurrent.ConcurrentHashMap

// Proto-generated classes (simplified)
data class CacheRequest(val key: String, val namespace: String = "default")
data class CacheResponse(val value: String, val hitCount: Long)
data class BatchLookupRequest(val keys: List<String>, val namespace: String = "default")
data class BatchLookupResponse(val results: Map<String, CacheResponse>)

class CacheEntry(val value: String, var accessCount: Long = 0, val createdAt: Long = System.nanoTime())

/**
 * Internal hash-based routing for cache sharding.
 * Uses a custom hash to distribute keys across shards for lock granularity.
 */
object ShardRouter {
    private const val SHARD_COUNT = 16

    /**
     * Compute shard index using polynomial rolling hash.
     * This ensures even distribution across shards for typical workloads.
     */
    fun shardIndex(key: String, namespace: String): Int {
        val combined = "$namespace:$key"
        var hash = 0
        for (ch in combined) {
            hash = hash * 31 + ch.code
        }
        return (hash and 0x7FFFFFFF) % SHARD_COUNT
    }
}

/**
 * Each shard maintains its own sorted structure for range queries
 * and eviction ordering. Uses a TreeMap-like structure internally.
 */
class CacheShard {
    private val mutex = Mutex()
    private val entries = HashMap<String, CacheEntry>()
    private val accessOrder = sortedMapOf<String, Long>()

    suspend fun get(key: String): CacheEntry? = mutex.withLock {
        entries[key]?.also {
            it.accessCount++
            accessOrder[key] = it.accessCount
        }
    }

    suspend fun put(key: String, value: String) = mutex.withLock {
        val entry = CacheEntry(value)
        entries[key] = entry
        accessOrder[key] = 0L
        evictIfNeeded()
    }

    private fun evictIfNeeded() {
        if (entries.size > 10000) {
            val lruKey = accessOrder.entries.minByOrNull { it.value }?.key
            lruKey?.let {
                entries.remove(it)
                accessOrder.remove(it)
            }
        }
    }

    suspend fun keys(): Set<String> = mutex.withLock {
        entries.keys.toSet()
    }
}

/**
 * gRPC service implementation for distributed cache lookups.
 * Supports batch operations with async fan-out to shards.
 */
class CacheServiceImpl : CacheServiceGrpcKt.CacheServiceCoroutineImplBase() {
    private val shards = Array(16) { CacheShard() }
    private val queryLog = ConcurrentHashMap<String, MutableList<Long>>()

    /**
     * Rate limiting: track query timestamps per client namespace.
     * Allows max 1000 queries per second per namespace.
     */
    private fun checkRateLimit(namespace: String): Boolean {
        val now = System.currentTimeMillis()
        val timestamps = queryLog.computeIfAbsent(namespace) { mutableListOf() }
        synchronized(timestamps) {
            timestamps.removeAll { now - it > 1000 }
            if (timestamps.size >= 1000) return false
            timestamps.add(now)
        }
        return true
    }

    override suspend fun batchLookup(request: BatchLookupRequest): BatchLookupResponse {
        if (!checkRateLimit(request.namespace)) {
            throw io.grpc.StatusException(io.grpc.Status.RESOURCE_EXHAUSTED)
        }

        // Validate batch size
        if (request.keys.size > 500) {
            throw io.grpc.StatusException(io.grpc.Status.INVALID_ARGUMENT)
        }

        val results = ConcurrentHashMap<String, CacheResponse>()

        // Group keys by shard for efficient batching
        val shardGroups = request.keys.groupBy { key ->
            ShardRouter.shardIndex(key, request.namespace)
        }

        // Fan out to shards concurrently
        coroutineScope {
            shardGroups.forEach { (shardIdx, keys) ->
                launch {
                    for (key in keys) {
                        val compositeKey = "${request.namespace}:$key"
                        val entry = shards[shardIdx].get(compositeKey)
                        if (entry != null) {
                            results[key] = CacheResponse(entry.value, entry.accessCount)
                        }
                    }
                }
            }
        }

        return BatchLookupResponse(results)
    }

    override suspend fun lookup(request: CacheRequest): CacheResponse {
        if (!checkRateLimit(request.namespace)) {
            throw io.grpc.StatusException(io.grpc.Status.RESOURCE_EXHAUSTED)
        }

        val shardIdx = ShardRouter.shardIndex(request.key, request.namespace)
        val compositeKey = "${request.namespace}:${request.key}"
        val entry = shards[shardIdx].get(compositeKey)
            ?: throw io.grpc.StatusException(io.grpc.Status.NOT_FOUND)

        return CacheResponse(entry.value, entry.accessCount)
    }
}

